tokens.css:
--color-bg: #faf6ef;
--color-surface: #fffdf8;
--color-text: #2a1d17;
--color-text-muted: #6e6157;
--color-border: #e3dacb;
--color-primary: #2a1f61;
--color-on-primary: #ffffff;
--color-accent: #eb5e4e;
--color-on-accent: #26195b;
--font-display: "Syne", system-ui, sans-serif;
--font-body: "Epilogue", system-ui, sans-serif;
--text-sm: 14px;
--text-base: 18px;
--text-lg: 23px;
--text-xl: 28px;
--text-2xl: 35px;
--text-3xl: 44px;
--radius-control: 8px;
--radius-card: 16px;
--space-section: 120px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
